datasource db {
  provider = "postgresql"
  url      = env("DATABASE_URL")
}

generator client {
  provider = "prisma-client-js"
}

model Product {
  id         Int         @id @default(autoincrement())
  name       String
  price      Float
  inventory  Int
  orderItems OrderItem[]
}

model Coupon {
  id    Int    @id @default(autoincrement())
  code  String @unique
  type  String // "PERCENTAGE" or "FLAT"
  value Float
}

model Order {
  id         Int         @id @default(autoincrement())
  total      Float
  discount   Float
  subtotal   Float
  couponCode String?
  createdAt  DateTime    @default(now())
  items      OrderItem[]
}

model OrderItem {
  id        Int     @id @default(autoincrement())
  order     Order   @relation(fields: [orderId], references: [id])
  orderId   Int
  product   Product @relation(fields: [productId], references: [id])
  productId Int
  quantity  Int
  price     Float
}

import type { DbSeedFn } from "wasp/server"

export const devSeed: DbSeedFn = async (prisma) => {
  // Clear existing records
  await prisma.orderItem.deleteMany({});
  await prisma.order.deleteMany({});
  await prisma.product.deleteMany({});
  await prisma.coupon.deleteMany({});

  // Seed products
  await prisma.product.createMany({
    data: [
      { name: "Premium Wireless Headphones", price: 100.00, inventory: 10 },
      { name: "Ergonomic Mechanical Keyboard", price: 150.00, inventory: 1 },
    ],
  });

  // Seed coupons
  await prisma.coupon.createMany({
    data: [
      { code: "SAVE20", type: "PERCENTAGE", value: 20 },
      { code: "FLAT50", type: "FLAT", value: 50 },
    ],
  });

  console.log("Database seeded successfully!");
};

import { app, page, route, query, action } from "@wasp.sh/spec";
import { MainPage } from "./src/MainPage" with { type: "ref" };
import { devSeed } from "./src/dbSeeds" with { type: "ref" };
import { getProducts, validateCoupon } from "./src/queries" with { type: "ref" };
import { checkout } from "./src/actions" with { type: "ref" };

export default app({
  name: "app",
  title: "app",
  wasp: { version: "^0.24.0" },
  head: ["<link rel='icon' href='/favicon.ico' />"],
  db: {
    seeds: [devSeed],
  },
  spec: [
    route("RootRoute", "/", page(MainPage)),
    query(getProducts, { entities: ["Product"] }),
    query(validateCoupon, { entities: ["Coupon"] }),
    action(checkout, { entities: ["Product", "Coupon", "Order", "OrderItem"] }),
  ],
});

